import{describe,it,expect,beforeEach}from"vitest";import{CommandPaletteEngine}from"../../frontend/js-modules/command-palette.js";describe("CommandPaletteEngine",()=>{let e;beforeEach(()=>{e=new CommandPaletteEngine}),it("should initialize in closed state",()=>{expect(e.isOpen).toBe(!1),expect(e.selectedIndex).toBe(0)}),it("should toggle open/closed states",()=>{expect(e.toggle()).toBe(!0),expect(e.isOpen).toBe(!0),e.close(),expect(e.isOpen).toBe(!1)}),it("should filter commands by search query",()=>{const t=e.search("monuments");expect(t.length).toBe(1),expect(t[0].id).toBe("monuments")}),it("should navigate up and down within bounds",()=>{e.open(),expect(e.selectedIndex).toBe(0),e.navigate("down"),expect(e.selectedIndex).toBe(1),e.navigate("up"),expect(e.selectedIndex).toBe(0)}),it("should return currently selected command",()=>{e.open();const t=e.getSelectedCommand();expect(t.id).toBe("home")})});